mapper.select:
SELECT 
FROM geo_region
WHERE status = 1
  AND country_code = #{countryCode}
  AND path LIKE CONCAT(#{pathPrefix}, '%')

    AND level <= #{maxLevel}

ORDER BY level ASC, sort ASC, id ASC
LIMIT #{maxRows}

(
    SELECT 
    FROM geo_region
    WHERE status = 1
      AND country_code = #{countryCode}
      AND name LIKE CONCAT(#{keyword}, '%')

      AND level = #{level}

    ORDER BY level ASC, sort ASC, id ASC
    LIMIT #{limit}
)
UNION
(
    SELECT 
    FROM geo_region
    WHERE status = 1
      AND country_code = #{countryCode}
      AND name_en LIKE CONCAT(#{keyword}, '%')

      AND level = #{level}

    ORDER BY level ASC, sort ASC, id ASC
    LIMIT #{limit}
)
UNION
(
    SELECT 
    FROM geo_region
    WHERE status = 1
      AND country_code = #{countryCode}
      AND name_ch LIKE CONCAT(#{keyword}, '%')

      AND level = #{level}

    ORDER BY level ASC, sort ASC, id ASC
    LIMIT #{limit}
)
ORDER BY level ASC, sort ASC, id ASC
LIMIT #{limit}

SELECT parent_id AS parentId, COUNT(*) AS cnt FROM geo_region WHERE status = 1 AND parent_id IN
#{id}
GROUP BY parent_id

SELECT COUNT(1)
FROM geo_region


        AND country_code = #{countryCode}


        AND parent_id = #{parentId}


        AND level = #{level}


        AND status = #{status}


        AND source = #{source}


        AND (
            name LIKE CONCAT('%', #{keyword}, '%')
            OR name_en LIKE CONCAT('%', #{keyword}, '%')
            OR name_ch LIKE CONCAT('%', #{keyword}, '%')
            OR code LIKE CONCAT('%', #{keyword}, '%')
        )

SELECT 
FROM geo_region


        AND country_code = #{countryCode}


        AND parent_id = #{parentId}


        AND level = #{level}


        AND status = #{status}


        AND source = #{source}


        AND (
            name LIKE CONCAT('%', #{keyword}, '%')
            OR name_en LIKE CONCAT('%', #{keyword}, '%')
            OR name_ch LIKE CONCAT('%', #{keyword}, '%')
            OR code LIKE CONCAT('%', #{keyword}, '%')
        )


ORDER BY level ASC, sort ASC, id ASC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM geo_region
WHERE parent_id = #{parentId}
  AND (
    name = #{name}

        OR name_en = #{nameEn}

  )

    AND id != #{excludeId}

SELECT 
FROM geo_region
WHERE status = 1
  AND latitude IS NOT NULL
  AND longitude IS NOT NULL
  AND latitude BETWEEN #{minLat} AND #{maxLat}
  AND longitude BETWEEN #{minLon} AND #{maxLon}

  AND country_code = #{countryCode}


  AND level >= #{minLevel}


  AND level <= #{maxLevel}

LIMIT #{limit}

SELECT 
FROM geo_region
WHERE status = 1
  AND latitude IS NOT NULL
  AND longitude IS NOT NULL
  AND latitude BETWEEN #{minLat} AND #{maxLat}
  AND longitude BETWEEN #{minLon} AND #{maxLon}

  AND country_code = #{countryCode}


  AND level >= #{minLevel}


  AND level <= #{maxLevel}

ORDER BY (POW(latitude - #{lat}, 2) + POW(longitude - #{lon}, 2)) ASC
LIMIT #{limit}

SELECT r.id, r.parent_id AS parentId, r.country_code AS countryCode,
       r.name, r.name_en AS nameEn, r.name_ch AS nameCh, r.code, r.level,
       r.region_type AS regionType, r.path, r.is_leaf AS isLeaf,
       r.latitude, r.longitude, r.source, r.source_id AS sourceId,
       r.status, r.sort, r.created_at AS createdAt, r.updated_at AS updatedAt
FROM geo_region_point p
INNER JOIN geo_region r ON r.id = p.id AND r.status = 1
WHERE MBRContains(ST_GeomFromText(#{envelopeWkt}, 4326), p.location)
  AND ST_Distance_Sphere(p.location, ST_SRID(POINT(#{lon}, #{lat}), 4326)) <= #{maxDistanceM}

  AND r.country_code = #{countryCode}


  AND r.level >= #{minLevel}


  AND r.level <= #{maxLevel}

ORDER BY ST_Distance_Sphere(p.location, ST_SRID(POINT(#{lon}, #{lat}), 4326)) ASC
LIMIT #{limit}
